-- Generated executable query. Run with SQLite against indus_weave.db.
-- Flags paid OT more than 15% above computed OT; positive paid OT with zero computed OT is included and has NULL excess_pct.
SELECT month,department_name,computed_overtime_value computed_hours,paid_overtime_value paid_hours,ROUND(100.0*(paid_overtime_value-computed_overtime_value)/NULLIF(computed_overtime_value,0),2) excess_pct,CASE WHEN computed_overtime_value=0 AND paid_overtime_value>0 THEN 'Paid OT with zero computed OT' ELSE 'Paid OT exceeds computed by more than 15%' END exception_type FROM staging_overtime_reconciliation WHERE paid_overtime_value>computed_overtime_value*1.15 ORDER BY month,department_name;
